jsonTools.init:
function init(eli) {
  var STORE = "team_commentary";
  var FACETS = ["agreementType", "clauseId", "sectionKey", "company", "jurisdiction", "counterpartyCountry", "entityType"];
  // Facets nothing extracts yet — a rule using one can't fire, and the UI
  // says so rather than letting it look live.
  var UNRESOLVED = { company: 1, jurisdiction: 1, counterpartyCountry: 1, entityType: 1 };
  var TIERS = [
    { id: "advisory", label: "Advisory", bg: "#f1f5f9", fg: "#64748b", bar: "#94a3b8" },
    { id: "default", label: "Default", bg: "#ccfbf1", fg: "#0f766e", bar: "#0f766e" },
    { id: "strong", label: "Strong", bg: "#ffedd5", fg: "#b45309", bar: "#b45309" },
    { id: "mandatory", label: "Mandatory", bg: "#fee2e2", fg: "#991b1b", bar: "#991b1b" },
  ];
  var OPS = [
    { id: "eq", label: "=", n: 1 }, { id: "ne", label: "≠", n: 1 },
    { id: "in", label: "in", n: 2 }, { id: "nin", label: "not in", n: 2 },
  ];
  // ── Vocabularies. A facet with a known value set gets a dropdown so people
  //    can't fragment it ("University" / "university" / "Uni"). Every list
  //    keeps an "+ Other…" escape so a missing value never blocks anyone —
  //    anything typed is remembered and offered to the next author.
  var VOCAB = {
    entityType: ["company", "university", "individual", "government", "non-profit", "other"],
    agreementType: [],     // filled from the managed `agreement_types` store
    counterpartyCountry: ["US", "GB", "FR", "DE", "IT", "ES", "NL", "PL", "BR", "MX", "CA", "IN", "CN", "JP", "AU", "EU", "EEA"],
    jurisdiction: ["US-NY", "US-DE", "US-CA", "GB-ENG", "FR", "DE", "NL", "SG", "CH"],
  };
  var VOCAB_KEY = "team_guidance.vocabExtras";
  function vocabExtras() {
    try { return JSON.parse(eli.settings.get(VOCAB_KEY) || "{}") || {}; } catch (_) { return {}; }
  }
  function rememberValue(facet, value) {
    var v = String(value || "").trim();
    if (!v || !VOCAB[facet]) return;
    var known = (VOCAB[facet] || []).concat(vocabExtras()[facet] || []);
    for (var i = 0; i < known.length; i++) if (String(known[i]).toLowerCase() === v.toLowerCase()) return;
    var ex = vocabExtras();
    ex[facet] = (ex[facet] || []).concat([v]);
    try { eli.settings.set(VOCAB_KEY, JSON.stringify(ex)); } catch (_) {}
  }
  function vocabFor(facet) {
    if (!VOCAB[facet]) return null;                       // free-text facet
    var extra = vocabExtras()[facet] || [];
    var seen = {}, out = [];
    VOCAB[facet].concat(extra).forEach(function (v) {
      var k = String(v).toLowerCase();
      if (!seen[k]) { seen[k] = 1; out.push(String(v)); }
    });
    return out;
  }
  // Agreement types come from the same managed store Build Draft uses, so
  // this tool never invents a competing list.
  function loadAgreementTypes() {
    return Promise.resolve(eli.storage.getAll("agreement_types")).then(function (r) {
      var list = (Array.isArray(r) ? r : [])
        .filter(function (x) { return x && !x.pseudo; })
        .map(function (x) { return x.label || x.name || x.id; })
        .filter(Boolean);
      if (list.length) VOCAB.agreementType = list;
    }).catch(function () {});
  }

  function esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
  }
  function canon(s) {
    return String(s || "").toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_+|_+$/g, "");
  }
  function genId() { return "tc_" + Date.now().toString(36) + "_" + Math.random().toString(36).slice(2, 10); }
  function tierOf(r) { return String((r && r.tier) || "default"); }
  function tierMeta(id) {
    for (var i = 0; i < TIERS.length; i++) if (TIERS[i].id === id) return TIERS[i];
    return TIERS[1];
  }
  function fmtDate(iso) {
    try {
      var d = new Date(iso);
      if (isNaN(d.getTime())) return "";
      return d.toLocaleDateString(undefined, { year: "numeric", month: "short", day: "numeric" });
    } catch (_) { return ""; }
  }
  function identity() {
    var ident = (eli.tools && typeof eli.tools.userIdentity === "function") ? eli.tools.userIdentity() : {};
    var us = window.userSettings || {};
    return {
      name: (us.name || us.firstName || ident.name || "(unknown)"),
      email: (us.userEmail || ident.email || ""),
      group: (us.userGroup || ident.group || ""),
    };
  }

  function loadAll() {
    return Promise.resolve(eli.storage.getAll(STORE)).then(function (r) { return r || []; })
      .catch(function () { return []; });
  }

  // ── Playbook guidance, read-only ─────────────────────────────────────
  // Schema (per playbook_manager):
  //   { id: <agreementType>, clauseMapping: { libraryName, clauses: [...] } }
  //   clause: { id, sectionId (name), articleId, text, guidanceComment,
  //             lockClause, lockComment, approvalRequired, fallbacks:[{text}] }
  // Flattened into the same card shape as team rows so one library shows
  // everything. These are NEVER written back — the playbook is published
  // through its own pipeline.
  function loadPlaybookRows() {
    return Promise.resolve(eli.storage.getAll("playbooks")).then(function (rows) {
      var out = [];
      (rows || []).forEach(function (p) {
        if (!p || !p.id || String(p.id).charAt(0) === "_") return;
        var cm = (p.clauseMapping && typeof p.clauseMapping === "object") ? p.clauseMapping : p;
        var agType = p.agreementType || p.id;
        var lib = cm.libraryName || p.libraryName || "";
        (Array.isArray(cm.clauses) ? cm.clauses : []).forEach(function (c, i) {
          if (!c) return;
          var name = c.sectionId || c.id || ("Clause " + (i + 1));
          var conds = [{ facet: "agreementType", op: "eq", value: String(agType) },
                       { facet: "clauseId", op: "eq", value: String(name) }];
          var base = {
            _virtual: true, authorName: lib || "Colgate Playbook", authorGroup: agType,
            createdAt: p.updatedAt || p.createdAt || "", updatedAt: p.updatedAt || "",
            agreementType: agType, sectionLabel: name,
            conditions: conds, scope: scopeFromConditions(conds),
            status: "active", origin: "authored", libraryName: lib,
          };
          var g = String(c.guidanceComment || "").trim();
          if (g) out.push(Object.assign({}, base, {
            id: "pb::" + agType + "::" + name + "::g", source: "playbook",
            text: g, tier: c.approvalRequired ? "strong" : "default",
          }));
          if (c.lockClause) out.push(Object.assign({}, base, {
            id: "pb::" + agType + "::" + name + "::lock", source: "lock", tier: "mandatory",
            text: String(c.lockComment || "").trim() ||
              ("This clause is locked. Changes to " + name + " require approval before responding."),
          }));
          (Array.isArray(c.fallbacks) ? c.fallbacks : []).forEach(function (fb, fi) {
            var t = String((fb && (fb.text || fb.body)) || "").trim();
            if (!t) return;
            out.push(Object.assign({}, base, {
              id: "pb::" + agType + "::" + name + "::fb" + fi, source: "fallback", tier: "default",
              text: t, rationale: "Pre-approved fallback position — offer this rather than reverting.",
            }));
          });
        });
      });
      return out;
    }).catch(function () { return []; });
  }
  function put(row) { return Promise.resolve(eli.storage.put(STORE, row)).then(function () { return row; }); }

  // ── Source: who says so. Playbook-derived rows are read-only here.
  function sourceOf(r) {
    var tags = Array.isArray(r.tags) ? r.tags : [];
    if (r.source === "playbook" || tags.indexOf("playbook") >= 0) return "playbook";
    if (r.source === "fallback" || tags.indexOf("fallback") >= 0) return "fallback";
    if (r.source === "lock" || tags.indexOf("lock") >= 0) return "lock";
    if (r.origin === "derived" || tags.indexOf("eli-disagreement") >= 0) return "team";
    return "person";
  }
  function isReadOnly(r) { var s = sourceOf(r); return s === "playbook" || s === "fallback" || s === "lock"; }
  function srcBadge(r) {
    var s = sourceOf(r), st, txt;
    if (s === "playbook") { st = "background:#1e3a8a;color:#fff;border:1px solid #16306e;"; txt = "📕 Colgate Playbook"; }
    else if (s === "fallback") { st = "background:#fffdf6;color:#7c4a03;border:1px solid #c9a227;"; txt = "📗 Playbook fallback"; }
    else if (s === "lock") { st = "background:#450a0a;color:#fecaca;border:1px solid #7f1d1d;"; txt = "🔒 Locked clause"; }
    else if (s === "team") {
      var n = (Array.isArray(r.evidence) ? r.evidence.length : 0);
      st = "background:#0f766e;color:#fff;border:1px solid #0d5c56;";
      txt = "👥 Team" + (n ? " · " + n + " evidence" : "");
    } else { st = "background:#fff;color:#0f766e;border:1px solid #0f766e;"; txt = "👤 " + (r.authorName || "Unknown"); }
    return '<span style="font:800 8.5px/1 Inter,sans-serif;text-transform:uppercase;letter-spacing:.09em;padding:4px 8px;white-space:nowrap;display:inline-flex;align-items:center;gap:5px;' + st + '">' + esc(txt) + '</span>';
  }

  // ── Conditions. `scope` holds the equality facets the RR matcher honours
  //    today; `conditions` holds the full expression set. A rule whose
  //    conditions can't be expressed as equality is flagged, not silently
  //    treated as live.
  function conditionsOf(r) {
    if (Array.isArray(r.conditions) && r.conditions.length) return r.conditions;
    var out = [], sc = r.scope || {};
    FACETS.forEach(function (f) { if (sc[f]) out.push({ facet: f, op: "eq", value: String(sc[f]) }); });
    if (!out.length && r.sectionId) {
      var p = String(r.sectionId).split("::");
      if (p[0]) out.push({ facet: "agreementType", op: "eq", value: p[0] });
      if (p[1] || p[2]) out.push({ facet: "sectionKey", op: "eq", value: (p[1] || "") + "::" + (p[2] || "") });
    }
    return out;
  }
  function scopeFromConditions(conds) {
    var sc = {};
    FACETS.forEach(function (f) { sc[f] = null; });
    (conds || []).forEach(function (c) { if (c.op === "eq" && c.value) sc[c.facet] = c.value; });
    return sc;
  }
  function blockers(conds) {
    var b = { facts: [], ops: false };
    (conds || []).forEach(function (c) {
      if (UNRESOLVED[c.facet] && b.facts.indexOf(c.facet) < 0) b.facts.push(c.facet);
      if (c.op !== "eq") b.ops = true;
    });
    return b;
  }
  function condChip(c) {
    var op = c.op === "eq" ? "=" : c.op === "ne" ? "≠" : c.op === "in" ? "in" : "not in";
    var warn = UNRESOLVED[c.facet];
    return '<span style="font:700 10.5px Inter,sans-serif;padding:1px 7px;white-space:nowrap;display:inline-block;margin:1px 3px 1px 0;' +
      (warn ? 'background:#fff7ed;border:1px solid #fdba74;color:#9a3412;' : 'background:#f0fdfa;border:1px solid #99f6e4;color:#0f766e;') +
      '">' + esc(c.facet) + ' ' + esc(op) + ' ' + esc(c.value) + '</span>';
  }

  // ─────────────────────────────────────────────────────────────────────
  var overlay = null, rows = [], view = "lib", groupBy = "agreementType", srcFilter = "all", q = "", insOpen = false;
  var insBy = "person";   // Contributors panel: by person (default) or by agreement type
  var draft = null;   // open editor: {row, conds, isNew}

  function visible() {
    var ql = q.toLowerCase().trim();
    return rows.filter(function (r) {
      if (!r || r.status === "archived") return false;
      if (view === "pend") { if (r.status !== "pending") return false; }
      else if (r.status === "pending") return false;
      var s = sourceOf(r);
      if (srcFilter === "playbook" && !(s === "playbook" || s === "fallback" || s === "lock")) return false;
      if (srcFilter === "team" && (s === "playbook" || s === "fallback" || s === "lock")) return false;
      if (ql) {
        var hay = (r.text || "") + " " + (r.rationale || "") + " " + (r.reference || "") + " " + (r.authorName || "") +
          " " + conditionsOf(r).map(function (c) { return c.facet + c.value; }).join(" ");
        if (hay.toLowerCase().indexOf(ql) < 0) return false;
      }
      return true;
    });
  }
  function groupKey(r) {
    if (groupBy === "agreementType") {
      var at = (r.scope && r.scope.agreementType) || r.agreementType || "";
      return at ? String(at).toUpperCase() : "All agreements";
    }
    if (groupBy === "clause") {
      var cl = (r.scope && r.scope.clauseId) || r.sectionLabel || "";
      return cl || "Unmapped";
    }
    if (groupBy === "source") {
      var s = sourceOf(r);
      return s === "person" ? "Written by people" : s === "team" ? "Derived from reviews" : "Colgate playbook";
    }
    return "Recently added";
  }

  function ruleCard(r) {
    var conds = conditionsOf(r), tm = tierMeta(tierOf(r)), ro = isReadOnly(r), bl = blockers(conds);
    var legacy = !r.scope && !r.conditions;
    return '<div data-tg-card="' + esc(r.id) + '" style="background:' + (ro ? "linear-gradient(180deg,#fdfcf7,#fbf9f0)" : "#fff") +
        ';border:1px solid #dbe3ec;border-left:3px solid ' + tm.bar + ';padding:13px 15px;margin-bottom:8px;">' +
      '<div style="display:flex;align-items:flex-start;gap:9px;flex-wrap:wrap;margin-bottom:7px;">' +
        srcBadge(r) +
        '<span style="font:800 8.5px/1 Inter,sans-serif;text-transform:uppercase;letter-spacing:.08em;padding:3px 7px;background:' + tm.bg + ';color:' + tm.fg + ';white-space:nowrap;">' + esc(tm.label) + '</span>' +
        (legacy ? '<span style="font:700 9px Inter,sans-serif;color:#94a3b8;background:#f8fafc;border:1px solid #e2e8f0;padding:1px 6px;text-transform:uppercase;letter-spacing:.05em;">Legacy · unreviewed</span>' : '') +
        '<span style="font:600 13.5px/1.55 Inter,sans-serif;color:#0f172a;flex:1;min-width:240px;white-space:pre-wrap;">' + esc(r.text || "") + '</span>' +
      '</div>' +
      '<div style="font:500 11px/1.6 Inter,sans-serif;color:#475569;margin-bottom:6px;">' +
        (conds.length ? 'Applies when ' + conds.map(condChip).join("")
          : '<span style="font:700 10.5px Inter,sans-serif;background:#f8fafc;border:1px solid #e2e8f0;color:#94a3b8;padding:1px 7px;">any agreement</span>') +
      '</div>' +
      (r.trigger ? '<div style="font:500 11px/1.55 Inter,sans-serif;color:#0f766e;background:#f0fdfa;border:1px solid #99f6e4;border-left:3px solid #0f766e;padding:6px 9px;margin-bottom:7px;">' +
        '<b style="font:800 8.5px Inter,sans-serif;text-transform:uppercase;letter-spacing:.08em;">Only when</b> ' + esc(r.trigger) + '</div>' : '') +
      (r.action ? '<div style="font:500 11px/1.55 Inter,sans-serif;color:#78350f;background:#fffbeb;border:1px solid #fbbf24;border-left:3px solid #d97706;padding:6px 9px;margin-bottom:7px;">' +
        '<b style="font:800 8.5px Inter,sans-serif;text-transform:uppercase;letter-spacing:.08em;">⚠ Escalate first</b> ' + esc(r.action) + '</div>' : '') +
      (r.rationale ? '<div style="font:400 11.5px/1.55 Inter,sans-serif;color:#475569;margin-bottom:7px;">' + esc(r.rationale) +
        (r.reference ? ' <span style="font:600 10.5px Inter,sans-serif;color:#7c4a03;background:#fffdf6;border:1px solid #e6d28a;padding:1px 6px;">' + esc(r.reference) + '</span>' : '') + '</div>' : '') +
      (bl.facts.length || bl.ops
        ? '<div style="font:700 9.5px Inter,sans-serif;color:#9a3412;background:#fff7ed;border:1px solid #fdba74;padding:3px 8px;display:inline-block;margin-bottom:7px;">⚠ Cannot fire yet — ' +
            (bl.facts.length ? esc(bl.facts.join(", ")) + ' not extracted from documents' : '') +
            (bl.facts.length && bl.ops ? ' · ' : '') +
            (bl.ops ? 'non-equality conditions not yet enforced' : '') + '</div>'
        : '') +
      '<div style="display:flex;align-items:center;gap:9px;flex-wrap:wrap;padding-top:7px;border-top:1px solid #f1f5f9;font:500 10px/1.4 Inter,sans-serif;color:#94a3b8;">' +
        (ro ? '<span style="font:600 9.5px Inter,sans-serif;color:#64748b;background:#f1f5f9;border:1px solid #e2e8f0;padding:2px 7px;">🔒 Read-only</span>' : '') +
        '<span><b style="color:#64748b;">' + esc(r.authorName || "Unknown") + '</b>' + (r.authorGroup ? ' · ' + esc(r.authorGroup) : '') + '</span>' +
        '<span>' + esc(fmtDate(r.createdAt)) + '</span>' +
        (r.updatedAt && r.updatedAt !== r.createdAt ? '<span>· edited ' + esc(fmtDate(r.updatedAt)) + '</span>' : '') +
        (typeof r.firedCount === "number" ? '<span>· fired <b style="color:#64748b;">' + r.firedCount + '×</b></span>' : '') +
        '<span style="margin-left:auto;display:flex;gap:6px;">' +
          (ro ? '' : '<button data-tg-edit="' + esc(r.id) + '" style="font:700 9.5px Inter,sans-serif;color:#0f766e;background:#f0fdfa;border:1px solid #99f6e4;padding:3px 9px;cursor:pointer;">Edit</button>') +
          (ro ? '' : '<button data-tg-archive="' + esc(r.id) + '" style="font:700 9.5px Inter,sans-serif;color:#94a3b8;background:#fff;border:1px solid #e2e8f0;padding:3px 9px;cursor:pointer;">Archive</button>') +
        '</span>' +
      '</div>' +
    '</div>';
  }

  function pendCard(r) {
    var conds = conditionsOf(r);
    return '<div style="background:#fff;border:1px solid #dbe3ec;border-left:3px solid #b45309;padding:13px 15px;margin-bottom:8px;">' +
      '<div style="display:flex;align-items:flex-start;gap:9px;flex-wrap:wrap;margin-bottom:7px;">' +
        '<span style="font:800 8.5px/1 Inter,sans-serif;text-transform:uppercase;letter-spacing:.08em;padding:3px 7px;background:#ffedd5;color:#b45309;">Pending</span>' +
        srcBadge(r) +
        '<span style="font:600 13px/1.55 Inter,sans-serif;color:#0f172a;flex:1;min-width:240px;white-space:pre-wrap;">' + esc(r.text || "") + '</span>' +
      '</div>' +
      '<div style="font:500 11px/1.6 Inter,sans-serif;color:#475569;margin-bottom:9px;">' + conds.map(condChip).join("") + '</div>' +
      '<div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;">' +
        '<button data-tg-promote="' + esc(r.id) + '" style="padding:7px 14px;font:800 10px/1 Inter,sans-serif;text-transform:uppercase;letter-spacing:.05em;cursor:pointer;background:linear-gradient(135deg,#0f766e,#0d5c56);color:#fff;border:1px solid #0d5c56;">✓ Promote to rule</button>' +
        '<button data-tg-edit="' + esc(r.id) + '" style="padding:7px 12px;font:800 10px/1 Inter,sans-serif;text-transform:uppercase;cursor:pointer;background:#fff;color:#475569;border:1px solid #cbd5e1;">Edit first</button>' +
        '<button data-tg-archive="' + esc(r.id) + '" style="padding:7px 12px;font:800 10px/1 Inter,sans-serif;text-transform:uppercase;cursor:pointer;background:#fff;color:#94a3b8;border:1px solid #e2e8f0;">Dismiss</button>' +
        '<span style="margin-left:auto;font:500 10px Inter,sans-serif;color:#94a3b8;font-style:italic;">' + esc(r.authorName || "") + ' · ' + esc(fmtDate(r.createdAt)) + ' · evidence never reaches the model</span>' +
      '</div>' +
    '</div>';
  }

  function insightsHtml() {
    var byPerson = {}, byType = {}, blocked = {}, active = 0, pending = 0;
    rows.forEach(function (r) {
      if (!r || r.status === "archived") return;
      if (r.status === "pending") { pending++; return; }
      active++;
      // People only — a playbook row's "author" is a library, not a person.
      if (!r._virtual) byPerson[r.authorName || "Unknown"] = (byPerson[r.authorName || "Unknown"] || 0) + 1;
      // Coverage counts everything, since that's the useful question.
      var at = (r.scope && r.scope.agreementType) || r.agreementType || "All agreements";
      byType[String(at).toUpperCase()] = (byType[String(at).toUpperCase()] || 0) + 1;
      blockers(conditionsOf(r)).facts.forEach(function (f) { blocked[f] = (blocked[f] || 0) + 1; });
    });
    var src = insBy === "type" ? byType : byPerson;
    var top = Object.keys(src).map(function (k) { return { k: k, n: src[k] }; })
      .sort(function (a, b) { return b.n - a.n; }).slice(0, 8);
    var max = top.length ? top[0].n : 1;
    var bl = Object.keys(blocked).map(function (k) { return { k: k, n: blocked[k] }; }).sort(function (a, b) { return b.n - a.n; });
    var tog = function (id, label) {
      var on = insBy === id;
      return '<button data-tg-insby="' + id + '" style="padding:3px 8px;font:700 8.5px/1 Inter,sans-serif;text-transform:uppercase;letter-spacing:.05em;cursor:pointer;border:1px solid ' +
        (on ? "#0f766e" : "#1e293b") + ';background:' + (on ? "#0f766e" : "transparent") + ';color:' + (on ? "#fff" : "#64748b") + ';">' + label + '</button>';
    };
    return '<div style="background:#0f172a;color:#cbd5e1;padding:16px 26px;border-bottom:1px solid #1e293b;">' +
      '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:12px;">' +
        '<div style="background:#111c33;border:1px solid #1e293b;padding:11px 13px;">' +
          '<div style="display:flex;align-items:center;gap:6px;margin-bottom:8px;flex-wrap:wrap;">' +
            '<span style="font:800 9px/1 Inter,sans-serif;text-transform:uppercase;letter-spacing:.1em;color:#64748b;flex:1;">' +
              (insBy === "type" ? "Coverage by agreement" : "Contributors") + '</span>' +
            tog("person", "Person") + tog("type", "Agreement") +
          '</div>' +
          (top.length ? top.map(function (t) {
            return '<div style="display:flex;gap:8px;font:600 11px/1.7 Inter,sans-serif;"><span style="flex:1;color:#e2e8f0;">' + esc(t.k) + '</span><span style="color:#64748b;">' + t.n + '</span></div>' +
              '<div style="height:5px;background:#0f766e;width:' + Math.round(t.n / max * 100) + '%;"></div>';
          }).join("") : '<div style="font:500 11px Inter,sans-serif;color:#64748b;">' +
              (insBy === "type" ? "Nothing to chart yet." : "No one has written guidance yet — playbook rules aren\'t counted here.") + '</div>') +
        '</div>' +
        '<div style="background:#111c33;border:1px solid #1e293b;padding:11px 13px;">' +
          '<div style="font:800 9px/1 Inter,sans-serif;text-transform:uppercase;letter-spacing:.1em;color:#64748b;margin-bottom:8px;">Blocked on fact extraction</div>' +
          (bl.length ? bl.map(function (t) {
            return '<div style="display:flex;gap:8px;font:600 11px/1.7 Inter,sans-serif;"><span style="flex:1;color:#e2e8f0;">' + esc(t.k) + '</span><span style="color:#fbbf24;">' + t.n + ' rule' + (t.n === 1 ? "" : "s") + '</span></div>';
          }).join("") + '<div style="font:500 10px/1.5 Inter,sans-serif;color:#64748b;margin-top:7px;font-style:italic;">Ranked demand — build extraction in this order.</div>'
            : '<div style="font:500 11px Inter,sans-serif;color:#64748b;">Nothing blocked.</div>') +
        '</div>' +
        '<div style="background:#111c33;border:1px solid #1e293b;padding:11px 13px;">' +
          '<div style="font:800 9px/1 Inter,sans-serif;text-transform:uppercase;letter-spacing:.1em;color:#64748b;margin-bottom:8px;">Store</div>' +
          '<div style="font:600 11px/1.9 Inter,sans-serif;color:#e2e8f0;">' + active + ' active · ' + pending + ' pending</div>' +
          '<div style="font:500 10px/1.5 Inter,sans-serif;color:#64748b;margin-top:5px;">Fire counts land with the next telemetry push.</div>' +
        '</div>' +
      '</div>' +
    '</div>';
  }

  // Known-vocabulary facets get a dropdown; "+ Other…" swaps in a text box
  // and whatever is typed joins the list for next time. Free-text facets
  // (sectionKey, clauseId, company) stay plain inputs.
  function _valueFieldHtml(c, i) {
    var vocab = vocabFor(c.facet);
    var base = 'flex:1;min-width:0;padding:7px 9px;font:600 11.5px Inter,sans-serif;border:1px solid #cbd5e1;background:#fff;';
    if (!vocab || c._other) {
      return '<input data-tg-cv="' + i + '" value="' + esc(c.value) + '" placeholder="' + (vocab ? "new value" : "value") + '" style="' + base + '">' +
        (vocab ? '<button data-tg-cpick="' + i + '" title="Back to the list" style="padding:6px 9px;font:700 11px Inter,sans-serif;color:#0f766e;background:#f0fdfa;border:1px solid #99f6e4;cursor:pointer;">▾</button>' : '');
    }
    var inList = !c.value || vocab.some(function (v) { return v.toLowerCase() === String(c.value).toLowerCase(); });
    return '<select data-tg-cv="' + i + '" style="' + base + 'cursor:pointer;">' +
      '<option value=""' + (c.value ? "" : " selected") + '>— choose —</option>' +
      vocab.map(function (v) {
        return '<option value="' + esc(v) + '"' + (String(c.value).toLowerCase() === v.toLowerCase() ? " selected" : "") + '>' + esc(v) + '</option>';
      }).join("") +
      (inList ? "" : '<option value="' + esc(c.value) + '" selected>' + esc(c.value) + '</option>') +
      '<option value="__other__">+ Other…</option>' +
    '</select>';
  }

  // ── SCAN ─────────────────────────────────────────────────────────────
  // Testing surface for the two-stage model: facets decide which rules are
  // CONSIDERED (free, deterministic); the model decides which of those
  // actually FIRE against the document (one batched call, only for rules
  // that carry a trigger). Facts are set by hand here because nothing
  // extracts entityType / country yet — that's the point of the harness.
  var scan = null;   // { open, facts, busy, sections, result, error }

  // PREFERRED source: Review Redlines' session. It already holds the real
  // OOXML diff (ordered ins/del/unchanged segments per paragraph) and the
  // real playbook clause mapping. Re-deriving either from paragraph text
  // was why the scanner was blind to redlines and guessed at clause names —
  // the whole point of this harness is to see what those tools see.
  function scanFromSession() {
    var sess = (window.TrackChangesPort && typeof window.TrackChangesPort.getSession === "function")
      ? window.TrackChangesPort.getSession() : null;
    var rowsIn = (sess && Array.isArray(sess.rawChanges)) ? sess.rawChanges : null;
    if (!rowsIn || !rowsIn.length) return null;
    var out = [];
    rowsIn.forEach(function (r, i) {
      if (!r) return;
      var mc = r.mappedClause || null;
      var clauseId = mc ? String(mc.sectionId || mc.name || mc.articleId || "") : "";
      var heading = clauseId || r.sectionLabel || r.articleLabel || ("¶" + ((r.sourceParagraphIndex != null ? r.sourceParagraphIndex : i) + 1));
      // Annotate the redline inline, the way RR shows it to the model, so a
      // trigger about what the counterparty DID has something to match on.
      var segs = Array.isArray(r.changeSegments) ? r.changeSegments : [];
      var body = "";
      if (segs.length) {
        segs.forEach(function (sg) {
          var t = String((sg && sg.text) || "");
          if (!t) return;
          var ty = String((sg && sg.type) || "").toLowerCase();
          if (ty === "ins") body += "[INSERTED by counterparty: " + t + "]";
          else if (ty === "del") body += "[DELETED by counterparty: " + t + "]";
          else body += t;
        });
      } else {
        body = String(r.plainText || "");
      }
      if (!body.trim()) return;
      out.push({ heading: heading, text: body, clauseId: clauseId, redlined: segs.length > 0 });
    });
    return out.length ? out : null;
  }

  function scanReadDoc() {
    var fromSess = scanFromSession();
    if (fromSess) return Promise.resolve({ sections: fromSess.slice(0, 80), source: "session" });
    if (!eli.host || typeof eli.host.runRaw !== "function") {
      return Promise.resolve({ error: "No Word host available." });
    }
    // Standalone read — reads tracked changes itself so it never depends on
    // Review Redlines having run. Two syncs: paragraph text, then each
    // paragraph's tracked changes, annotated inline so a trigger about what
    // the counterparty DID has something to match on.
    return eli.host.runRaw("team_guidance:scan", function (context) {
      var paras = context.document.body.paragraphs;
      paras.load("items/text");
      return context.sync().then(function () {
        var items = paras.items || [];
        var tcs = items.map(function (p) {
          var tc = p.getTrackedChanges();
          tc.load("items/type,items/text");
          return tc;
        });
        return context.sync().then(function () {
          var out = [], cur = null, redlined = 0;
          items.forEach(function (p, i) {
            var t = String(p.text || "").trim();
            var marks = "";
            var list = (tcs[i] && tcs[i].items) || [];
            list.forEach(function (c) {
              var ct = String((c && c.text) || "").trim();
              if (!ct) return;
              var ty = String((c && c.type) || "").toLowerCase();
              if (ty.indexOf("del") === 0) marks += " [DELETED by counterparty: " + ct + "]";
              else if (ty.indexOf("ins") === 0) marks += " [INSERTED by counterparty: " + ct + "]";
            });
            if (marks) redlined++;
            if (!t && !marks) return;
            var isHead = !marks && t && (
              /^(article|section|exhibit|schedule|appendix)\b/i.test(t) ||
              /^\s*\d+(\.\d+)*\s*[.\-—)]?\s+\S/.test(t) ||
              /^§/.test(t) ||
              (t.length < 80 && t === t.toUpperCase() && /[A-Z]{3}/.test(t)) ||
              (t.length < 70 && !/[.;:]$/.test(t) && /^[A-Z]/.test(t) && t.split(/\s+/).length <= 8));
            if (isHead && t.length < 120) { cur = { heading: t, text: "", clauseId: "", redlined: false }; out.push(cur); return; }
            if (!cur) { cur = { heading: "(preamble)", text: "", clauseId: "", redlined: false }; out.push(cur); }
            cur.text += (cur.text ? "\n" : "") + t + marks;
            if (marks) cur.redlined = true;
          });
          return {
            sections: out.filter(function (s) { return s.text.length > 40; }).slice(0, 80),
            source: "document", redlinedParas: redlined,
          };
        });
      });
    }).catch(function (e) { return { error: (e && e.message) || String(e) }; });
  }

  // Stage 1 — pure facet match. No AI, fully explainable.
  function scanCandidates(facts) {
    return rows.filter(function (r) {
      if (!r || r.status !== "active") return false;
      var conds = conditionsOf(r);
      for (var i = 0; i < conds.length; i++) {
        var c = conds[i];
        if (c.facet === "clauseId" || c.facet === "sectionKey") continue;  // matched per-section, not per-doc
        var have = facts[c.facet];
        if (!have) return false;                       // fact unknown → can't confirm → exclude
        var want = String(c.value || "").toLowerCase();
        var got = String(have).toLowerCase();
        if (c.op === "eq" && got !== want) return false;
        if (c.op === "ne" && got === want) return false;
        if (c.op === "in" && want.split(/[,\s]+/).indexOf(got) < 0 && want !== got) return false;
        if (c.op === "nin" && (want.split(/[,\s]+/).indexOf(got) >= 0 || want === got)) return false;
      }
      return true;
    });
  }

  // Stage 1.5 — clause localisation. Playbook guidance is POSITIONAL, not
  // conditional: it applies where its clause is, and not at all where the
  // clause is absent. Token overlap on headings; no AI.
  function _normTokens(str) {
    return String(str || "").toLowerCase()
      .replace(/[§¶]/g, " ")
      .replace(/\b(article|section|clause|the|of|and|for|to|a|an|any|its)\b/g, " ")
      .replace(/[^a-z0-9]+/g, " ")
      .split(/\s+/)
      .filter(function (t) { return t && t.length > 2 && !/^\d+$/.test(t) && !/^[ivxlc]{1,4}$/.test(t); });
  }
  function _matchSections(clauseId, sections) {
    var want = _normTokens(clauseId);
    if (!want.length) return [];
    // When the section came from RR's session it carries the clause the
    // playbook mapper actually assigned — trust that over any guessing.
    var exact = (sections || []).filter(function (sec) {
      return sec.clauseId && canon(sec.clauseId) === canon(clauseId);
    });
    if (exact.length) return exact.map(function (sec) { return { sec: sec, score: 1, exact: true }; }).slice(0, 3);
    var hits = [];
    (sections || []).forEach(function (sec) {
      var have = _normTokens(sec.clauseId || sec.heading);
      if (!have.length) return;
      var n = 0;
      want.forEach(function (w) { if (have.indexOf(w) >= 0) n++; });
      var score = n / want.length;
      if (score >= 0.6) hits.push({ sec: sec, score: score });
    });
    return hits.sort(function (a, b) { return b.score - a.score; }).slice(0, 3);
  }
  function _clauseIdOf(r) {
    var c = conditionsOf(r).filter(function (x) { return x.facet === "clauseId" && x.value; })[0];
    return c ? String(c.value) : "";
  }

  // ── The evaluator, mirroring Review Redlines' end-of-review auditor ──
  // RR doesn't test guidance against raw text — it writes a NET IMPACT for
  // each section first, then asks whether that impact relates to the
  // guidance. Working from an interpretation rather than from words is why
  // it catches things a literal trigger test misses.
  //
  // Two phases, and two different bars in phase B (RR's design):
  //   • team guidance — LOOSE. A human deliberately left this note; surface
  //     it whenever it is reasonably on point.
  //   • playbook      — STRICT. Flag only where it speaks directly to the
  //     issue the redlines raised.
  // A rule carrying an explicit trigger is judged strictly regardless.

  function _chunk(arr, n) {
    var out = [];
    for (var i = 0; i < arr.length; i += n) out.push(arr.slice(i, i + n));
    return out;
  }

  // Phase A — what do the redlines in each section actually do?
  function scanNetImpacts(sections) {
    var redlined = sections.filter(function (s) { return s.redlined; });
    if (!redlined.length) return Promise.resolve({});
    if (!eli.ai || typeof eli.ai.completeJSON !== "function") return Promise.resolve({});
    var jobs = _chunk(redlined, 8).map(function (batch) {
      var prompt =
        "You are a senior Colgate-Palmolive contracts attorney. For EACH section below, the counterparty's " +
        "tracked changes are marked inline as [INSERTED by counterparty: ...] and [DELETED by counterparty: ...].\n\n" +
        "For each section write netImpact: 2-3 sentences stating what those changes DO to Colgate's position — " +
        "the obligation or right that moved, and in whose favour. State only what the marked changes show. " +
        "If the changes are immaterial (formatting, cross-references, typos), say so plainly.\n\n" +
        batch.map(function (s, i) {
          return "[" + (i + 1) + "] heading=" + s.heading + "\n" + String(s.text).slice(0, 3000);
        }).join("\n\n---\n\n") +
        "\n\nReturn ONLY JSON:\n{ \"sections\": [ { \"heading\": \"<exact heading>\", \"netImpact\": \"<2-3 sentences>\" } ] }";
      return Promise.resolve(eli.ai.completeJSON(prompt)).then(function (res) {
        var out = {};
        var list = (res && (res.sections || res)) || [];
        (Array.isArray(list) ? list : []).forEach(function (x) {
          if (x && x.heading) out[String(x.heading)] = String(x.netImpact || "").trim();
        });
        return out;
      }).catch(function () { return {}; });
    });
    return Promise.all(jobs).then(function (maps) {
      var all = {};
      maps.forEach(function (m) { Object.keys(m).forEach(function (k) { all[k] = m[k]; }); });
      return all;
    });
  }

  // Phase B — does that net impact relate to the rules in play here?
  function scanAudit(units) {
    var live = units.filter(function (u) { return u.rules.length && (u.netImpact || u.sectionText); });
    if (!live.length) return Promise.resolve({});
    if (!eli.ai || typeof eli.ai.completeJSON !== "function") return Promise.resolve({});
    var jobs = _chunk(live, 6).map(function (batch) {
      var body = batch.map(function (u, i) {
        return "[" + (i + 1) + "] SECTION: " + u.heading + "\n" +
          "netImpact: " + (u.netImpact || "(no tracked changes in this section)") + "\n" +
          "RULES:\n" + u.rules.map(function (r) {
            return "  - id=" + r.id + " | source=" + (isReadOnly(r) ? "playbook" : "team") +
              " | weight=" + String(r.tier || "default").toUpperCase() +
              (String(r.trigger || "").trim() ? "\n    TRIGGER (must be literally met): " + String(r.trigger).trim() : "") +
              "\n    GUIDANCE: " + String(r.text || "").trim();
          }).join("\n");
      }).join("\n\n---\n\n");
      var prompt =
        "You are a senior Colgate-Palmolive contracts attorney running a FINAL AUDIT over a redlined contract.\n\n" +
        "For each section you have netImpact — what the redlines do to Colgate — and the rules that apply here.\n\n" +
        "Decide, for EVERY rule listed, whether it should be flagged for this section. The bars differ by source:\n" +
        "  • team — a Colgate reviewer deliberately wrote this. Flag whenever it is REASONABLY ON POINT to what " +
        "the redlines did. Err on the side of surfacing it; skip only when clearly unrelated.\n" +
        "  • playbook — STRICTER. Flag only where it speaks DIRECTLY to the issue the redlines raised. Do not " +
        "flag tangential or generic overlap.\n" +
        "  • Any rule carrying a TRIGGER is judged STRICTLY against that trigger: flag only if the trigger is " +
        "literally met by what the redlines did. Do not infer.\n\n" +
        "Emit an entry for EVERY rule id you were given, flagged or not.\n\n" + body +
        "\n\nReturn ONLY JSON:\n{ \"results\": [ { \"id\": \"<rule id>\", \"heading\": \"<section heading>\", " +
        "\"flag\": true|false, \"why\": \"<one line: what in the redline it bears on, or why not>\" } ] }";
      return Promise.resolve(eli.ai.completeJSON(prompt)).then(function (res) {
        var out = {};
        var list = (res && (res.results || res)) || [];
        (Array.isArray(list) ? list : []).forEach(function (x) {
          if (x && x.id) out[String(x.id) + "@@" + String(x.heading || "")] = x;
        });
        return out;
      }).catch(function (e) { return { __error: (e && e.message) || String(e) }; });
    });
    return Promise.all(jobs).then(function (maps) {
      var all = {};
      maps.forEach(function (m) { Object.keys(m).forEach(function (k) { all[k] = m[k]; }); });
      return all;
    });
  }

  // Public: facts + document -> which rules apply where, and which the
  // redlines actually implicate. Registered on the tool API so other tools
  // can consume it without reimplementing any of this.
  function evaluateGuidance(facts, sections) {
    var cands = scanCandidates(facts || {});
    var units = [], absent = [], docWide = [];
    cands.forEach(function (r) {
      var cid = _clauseIdOf(r);
      if (!cid) { docWide.push(r); return; }
      var hits = _matchSections(cid, sections);
      if (!hits.length) { absent.push({ r: r, clauseId: cid }); return; }
      hits.slice(0, 1).forEach(function (h) {
        var u = null;
        units.forEach(function (x) { if (x.heading === h.sec.heading) u = x; });
        if (!u) { u = { heading: h.sec.heading, sec: h.sec, rules: [] }; units.push(u); }
        u.rules.push(r);
      });
    });
    // Doc-wide rules ride along on every redlined section so the auditor can
    // see them against real movement rather than against nothing.
    var redlinedSecs = sections.filter(function (s) { return s.redlined; });
    docWide.forEach(function (r) {
      (redlinedSecs.length ? redlinedSecs : sections.slice(0, 1)).forEach(function (sec) {
        var u = null;
        units.forEach(function (x) { if (x.heading === sec.heading) u = x; });
        if (!u) { u = { heading: sec.heading, sec: sec, rules: [] }; units.push(u); }
        u.rules.push(r);
      });
    });
    return scanNetImpacts(sections).then(function (impacts) {
      units.forEach(function (u) {
        u.netImpact = impacts[u.heading] || "";
        u.sectionText = u.sec.text;
      });
      return scanAudit(units).then(function (verdicts) {
        return { units: units, absent: absent, verdicts: verdicts, impacts: impacts, docWide: docWide };
      });
    });
  }

  function runScan() {
    scan.busy = true; scan.error = ""; scan.result = null; render();
    return scanReadDoc().then(function (doc) {
      if (doc.error) { scan.busy = false; scan.error = doc.error; render(); return; }
      scan.sections = doc.sections || [];
      scan.source = doc.source || "";
      scan.redlinedParas = doc.redlinedParas || 0;
      return evaluateGuidance(scan.facts, scan.sections).then(function (res) {
        scan.busy = false;
        scan.result = res;
        render();
      }).catch(function (e) {
        scan.busy = false; scan.error = (e && e.message) || String(e); render();
      });
    });
  }

  function scanPanelHtml() {
    if (!scan || !scan.open) return "";
    var fi = "padding:7px 9px;font:600 11.5px Inter,sans-serif;border:1px solid #cbd5e1;background:#fff;";
    var pick = function (facet, label) {
      var vocab = vocabFor(facet) || [];
      return '<div style="display:flex;align-items:center;gap:6px;">' +
        '<span style="font:700 9.5px/1 Inter,sans-serif;color:#475569;min-width:118px;">' + label + '</span>' +
        '<select data-tg-fact="' + facet + '" style="' + fi + 'flex:1;cursor:pointer;">' +
          '<option value="">— unknown —</option>' +
          vocab.map(function (v) {
            return '<option value="' + esc(v) + '"' + (String(scan.facts[facet] || "") === v ? " selected" : "") + '>' + esc(v) + '</option>';
          }).join("") +
        '</select></div>';
    };
    var res = scan.result;
    var body;
    if (scan.busy) body = '<div style="padding:26px;text-align:center;font:600 12px Inter,sans-serif;color:#0f766e;">⏳ Reading the document and checking triggers…</div>';
    else if (scan.error) body = '<div style="padding:14px;font:500 12px/1.6 Inter,sans-serif;color:#991b1b;background:#fef2f2;border:1px solid #fecaca;">' + esc(scan.error) + '</div>';
    else if (!res) body = '<div style="padding:18px 0;font:500 11.5px/1.6 Inter,sans-serif;color:#94a3b8;">Set the facts above, then run the scan. Stage 1 narrows by facts with no AI; stage 2 checks each open-ended trigger against the document in one call.</div>';
    else {
      // Grouped by SECTION, the way the auditor thinks: here's what the
      // redlines did here, and here's the guidance that bears on it.
      var flagged = 0, quiet = 0, ruleCount = 0;
      res.units.forEach(function (u) {
        u.rules.forEach(function (r) {
          ruleCount++;
          var v = res.verdicts[r.id + "@@" + u.heading];
          if (v && v.flag) flagged++; else quiet++;
        });
      });
      var ruleLine = function (r, v, flag) {
        var tm = tierMeta(tierOf(r));
        return '<div style="padding:8px 10px;background:' + (flag ? "#fff" : "#fafbfc") + ';border:1px solid #e2e8f0;border-left:3px solid ' +
            (flag ? tm.bar : "#e2e8f0") + ';margin-bottom:5px;' + (flag ? "" : "opacity:.7;") + '">' +
          '<div style="display:flex;gap:7px;align-items:flex-start;flex-wrap:wrap;">' +
            '<span style="font:800 8.5px/1 Inter,sans-serif;text-transform:uppercase;padding:3px 7px;background:' + tm.bg + ';color:' + tm.fg + ';">' + tm.label + '</span>' +
            srcBadge(r) +
            (r.action ? '<span style="font:800 8.5px/1 Inter,sans-serif;text-transform:uppercase;padding:3px 7px;background:#fffbeb;color:#92400e;border:1px solid #fbbf24;">⚠ Escalate</span>' : '') +
            '<span style="flex:1;min-width:180px;font:600 11.5px/1.5 Inter,sans-serif;color:#0f172a;">' + esc(r.text || "") + '</span>' +
          '</div>' +
          (v && v.why ? '<div style="font:400 11px/1.5 Inter,sans-serif;color:' + (flag ? "#334155" : "#94a3b8") + ';margin-top:4px;">' + esc(v.why) + '</div>' : '') +
          (flag && r.action ? '<div style="font:600 11px/1.5 Inter,sans-serif;color:#78350f;background:#fffbeb;border:1px solid #fbbf24;padding:5px 8px;margin-top:6px;">Action: ' + esc(r.action) + '</div>' : '') +
        '</div>';
      };
      var units = res.units.slice().sort(function (a, b) {
        var af = a.rules.filter(function (r) { var v = res.verdicts[r.id + "@@" + a.heading]; return v && v.flag; }).length;
        var bf = b.rules.filter(function (r) { var v = res.verdicts[r.id + "@@" + b.heading]; return v && v.flag; }).length;
        return bf - af;
      });
      body =
        '<div style="padding:10px 12px;background:#f0fdfa;border:1px solid #99f6e4;font:600 11.5px/1.6 Inter,sans-serif;color:#0f766e;margin-bottom:10px;">' +
          ruleCount + ' rule check' + (ruleCount === 1 ? "" : "s") + ' across ' + res.units.length + ' section' + (res.units.length === 1 ? "" : "s") +
          ' · <b>' + flagged + ' flagged</b> · ' + quiet + ' not implicated · ' + res.absent.length + ' clause absent' +
          '<br>read ' + scan.sections.length + ' sections' +
          (scan.source === "session" ? ' via the Review Redlines session' : ' directly from the document') +
          (scan.redlinedParas ? ' · ' + scan.redlinedParas + ' redlined paragraph' + (scan.redlinedParas === 1 ? '' : 's') :
            (scan.source === "session" ? '' : ' · no tracked changes found')) +
          (res.verdicts.__error ? '<br><span style="color:#991b1b;">audit failed: ' + esc(res.verdicts.__error) + '</span>' : '') +
        '</div>' +
        units.map(function (u) {
          var flags = u.rules.filter(function (r) { var v = res.verdicts[r.id + "@@" + u.heading]; return v && v.flag; });
          return '<div style="margin-bottom:14px;">' +
