          '<div style="font:800 9px/1 Inter,sans-serif;text-transform:uppercase;letter-spacing:.09em;color:#94a3b8;">Facts — set by hand until extraction exists</div>' +
          pick("agreementType", "Agreement type") + pick("entityType", "Entity type") +
          pick("counterpartyCountry", "Counterparty country") + pick("jurisdiction", "Governing law") +
          '<button data-tg-runscan style="margin-top:5px;padding:9px 16px;font:800 11px Inter,sans-serif;text-transform:uppercase;letter-spacing:.05em;cursor:pointer;background:linear-gradient(135deg,#0f766e,#0d5c56);color:#fff;border:1px solid #0d5c56;">Run scan</button>' +
